const notes = new Map();
let counter = 0;

function nextId() {
  counter += 1;
  return `n${counter}`;
}

function isNonEmptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note with a title and body. Returns the generated note id.',
      inputSchema: {
        type: 'object',
        properties: {
          title: {
            type: 'string',
            description: 'Title of the note. Must be a non-empty string.',
          },
          body: {
            type: 'string',
            description: 'Body content of the note. Must be a non-empty string.',
          },
        },
        required: ['title', 'body'],
        additionalProperties: false,
      },
    },
    {
      name: 'note_get',
      description: 'Retrieve a previously created note by its id.',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: {
            type: 'string',
            description: 'Identifier of the note to retrieve.',
          },
        },
        required: ['note_id'],
        additionalProperties: false,
      },
    },
  ];
}

export async function callTool(name, args) {
  const params = args && typeof args === 'object' ? args : {};

  if (name === 'note_create') {
    const { title, body } = params;
    if (!isNonEmptyString(title)) {
      throw new Error('Invalid arguments: "title" must be a non-empty string.');
    }
    if (!isNonEmptyString(body)) {
      throw new Error('Invalid arguments: "body" must be a non-empty string.');
    }

    const id = nextId();
    notes.set(id, { title, body });

    return {
      content: [
        {
          type: 'text',
          text: `Created note ${id} titled "${title}".`,
        },
      ],
    };
  }

  if (name === 'note_get') {
    const { note_id } = params;
    if (!isNonEmptyString(note_id)) {
      throw new Error('Invalid arguments: "note_id" must be a non-empty string.');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Unknown note_id: ${note_id}`);
    }
    return {
      content: [
        {
          type: 'text',
          text: `Title: ${note.title}\n\n${note.body}`,
        },
      ],
    };
  }

  throw new Error(`Unknown tool: ${name}`);
}

